param([switch]$Aplicar)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
if (-not (Test-Path 'package.json')) { throw 'Ejecuta desde la raiz de LERABOT.' }
$rutas = @(
  'src/modulos/configuracion/ConfiguracionView.vue',
  'src/modulos/configuracion/servicios/configuracion.ts',
  'src/modulos/configuracion/estado/configuracion.ts',
  'backend/funciones/configuraciones/index.mjs'
)
foreach ($ruta in $rutas) { if (-not (Test-Path $ruta)) { throw ('Falta archivo: ' + $ruta) } }
Write-Host 'LERABOT: GET automatico + PUT Guardar, sin login ni modo demo'
foreach ($ruta in $rutas) { Write-Host (' - ' + $ruta) }
if (-not $Aplicar) { Write-Host 'Solo vista previa. Agrega -Aplicar para escribir los archivos.'; exit 0 }
$respaldo = Join-Path $env:TEMP ('LERABOT-GET-PUT-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
$utf8 = New-Object System.Text.UTF8Encoding($false)
foreach ($ruta in $rutas) {
  $destino = Join-Path $respaldo $ruta
  New-Item -ItemType Directory -Force -Path (Split-Path $destino) | Out-Null
  Copy-Item $ruta $destino -Force
}
Write-Host ('Respaldo: ' + $respaldo)
$ruta = 'src/modulos/configuracion/ConfiguracionView.vue'
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText((Join-Path (Get-Location).Path $ruta), $contenido, $utf8)
Write-Host ('Actualizado: ' + $ruta)
$ruta = 'src/modulos/configuracion/servicios/configuracion.ts'
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText((Join-Path (Get-Location).Path $ruta), $contenido, $utf8)
Write-Host ('Actualizado: ' + $ruta)
$ruta = 'src/modulos/configuracion/estado/configuracion.ts'
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText((Join-Path (Get-Location).Path $ruta), $contenido, $utf8)
Write-Host ('Actualizado: ' + $ruta)
$ruta = 'backend/funciones/configuraciones/index.mjs'
$contenido = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
[IO.File]::WriteAllText((Join-Path (Get-Location).Path $ruta), $contenido, $utf8)
Write-Host ('Actualizado: ' + $ruta)
Write-Host 'LISTO. No se ha conectado a AWS y no se ha desplegado nada.'
Write-Host 'Ahora: npm run type-check; npm run build; node --check backend/funciones/configuraciones/index.mjs'
Write-Host 'Copia backend/funciones/configuraciones/index.mjs a AWS Lambda y pulsa Deploy.'
Write-Host 'API Gateway: GET/PUT Authorization NONE y stage prd desplegado si cambias esa configuracion.'
